sys_script_include.script:
var addNumberBtn = Class.create();
addNumberBtn.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    addNumber: function(){
        var num = { 
            obj: 0
        };
        var currentNumStr = this.getParameter('sysparm_num') || '000';
        var currentNum = parseInt(currentNumStr, 10) || 0;
        var name = this.getParameter('sysparm_sys_name');
        var sys_id = this.getParameter('sysparm_sys_id'); 
        gs.error("当前编号: " + currentNumStr + " (" + currentNum + ") | 系统ID: " + sys_id);
        currentNum += 1;
        var formattedNum = this._formatNumber(currentNum);
        gs.info("递增后新编号: " + formattedNum);

        var p3 = new GlideRecord('x_1758202_demo_computers');
        if (p3.get(sys_id)) {
            gs.error("更新前原编号: " + p3.num);
            p3.num = formattedNum;
            p3.update();
            return formattedNum; 
        }
        return '';
    },
    _formatNumber: function(number) {
        var str = number.toString();
        while (str.length < 3) {
            str = '0' + str;
        }
        return str;
    },
    type: 'addNumberBtn'
});
